import{a as i}from"./chunk-U6657LB5.js";import{c as n,d as o,f as r}from"./chunk-AM72GXMS.js";var d=[{id:1,title:"C\xF3mo uso IA para acelerar mi desarrollo en Angular y .NET",excerpt:"Mi experiencia real integrando herramientas de IA (Claude, Copilot) en mi flujo de trabajo diario como Full Stack Developer y c\xF3mo ha transformado mi productividad.",date:"2026-03-15",category:"IA & Productividad",tags:["IA","Claude","Angular",".NET","Productividad"],readTime:6,content:[{type:"text",content:"Hace un a\xF1o ve\xEDa la IA generativa como una herramienta curiosa para generar texto. Hoy es parte integral de mi flujo de desarrollo. Desde la arquitectura de mi sistema ERP/POS Multi-Tenant hasta la creaci\xF3n de Prix-R9, la IA ha cambiado fundamentalmente c\xF3mo escribo, reviso y dise\xF1o software."},{type:"heading",content:"El cambio de mentalidad"},{type:"text",content:"El error m\xE1s com\xFAn que veo en desarrolladores es tratar a la IA como un autocompletado glorificado. Copiar y pegar c\xF3digo generado sin entenderlo es peor que escribirlo t\xFA mismo, porque introduces deuda t\xE9cnica invisible. Mi enfoque es diferente: uso la IA como un par programmer experto que me ayuda a pensar, no a evitar pensar."},{type:"text",content:'Por ejemplo, cuando dise\xF1\xE9 la arquitectura Multi-Tenant de mi sistema ERP, no le ped\xED a Claude "escr\xEDbeme un sistema Multi-Tenant". Le describ\xED mis restricciones (PostgreSQL, EF Core, separaci\xF3n de MasterContext y POSContext) y discutimos las opciones: \xBFbase de datos por tenant, schema por tenant, o discriminador por fila? Cada opci\xF3n tiene trade-offs reales que una IA puede ayudarte a evaluar si le das contexto suficiente.'},{type:"heading",content:"D\xF3nde la IA me ahorra m\xE1s tiempo"},{type:"list",items:["Scaffolding de componentes Angular: generar la estructura base de un componente standalone con signals, inputs y computed properties toma segundos.","Firmador electr\xF3nico DTE: depurar la especificaci\xF3n JSON del Ministerio de Hacienda y generar los schemas de validaci\xF3n fue 10x m\xE1s r\xE1pido con IA.","Tests unitarios: describir el comportamiento esperado y que la IA genere los test cases cubre edge cases que manualmente olvidar\xEDa.","Documentaci\xF3n de APIs: generar README, ejemplos de uso y documentaci\xF3n t\xE9cnica para librer\xEDas como RMapper y Prix-R9.","Refactoring: analizar c\xF3digo legacy, identificar patrones y proponer migraciones seguras."]},{type:"heading",content:"Mi flujo de trabajo con Claude"},{type:"text",content:"Claude Code es mi herramienta principal. Lo uso directamente en la terminal para trabajar con el codebase completo. El flujo t\xEDpico es:"},{type:"code",label:"Flujo t\xEDpico",content:`1. Describir la tarea con contexto del proyecto
2. Claude analiza los archivos relevantes
3. Discutimos la soluci\xF3n antes de implementar
4. Claude genera el c\xF3digo, yo reviso y ajusto
5. Build, test, deploy \u2014 todo desde la misma sesi\xF3n`},{type:"text",content:'Lo clave es dar contexto: no es lo mismo decir "hazme un servicio" que "necesito un servicio Angular que use rxResource para cargar proyectos del portafolio, con computed signals para filtrar por categor\xEDa y un m\xE9todo getById". La calidad del output es directamente proporcional a la calidad del prompt.'},{type:"heading",content:"Ejemplo real: Prix-R9"},{type:"text",content:"Cuando cre\xE9 Prix-R9 (mi CLI de pruebas de carga), la IA me ayud\xF3 a dise\xF1ar el sistema de extracci\xF3n de variables entre steps. El concepto era claro: ejecutar requests encadenados donde el response de uno alimenta el body del siguiente. Pero la implementaci\xF3n del JSONPath parser, el manejo de errores cascade y la generaci\xF3n del reporte ten\xEDan muchos edge cases que la IA me ayud\xF3 a cubrir sistem\xE1ticamente."},{type:"heading",content:"Lo que la IA no reemplaza"},{type:"list",items:["Decisiones de arquitectura: la IA propone, t\xFA decides. Nadie m\xE1s conoce las restricciones reales de tu proyecto.","Conocimiento del dominio: un sistema de facturaci\xF3n electr\xF3nica tiene reglas fiscales que solo un humano puede validar contra la normativa.","Code review cr\xEDtico: la IA puede generar c\xF3digo que compila y pasa tests pero tiene problemas de seguridad o rendimiento sutiles.","Relaciones con el equipo: la comunicaci\xF3n, mentoring y alineaci\xF3n de prioridades siguen siendo 100% humanas."]},{type:"heading",content:"Conclusi\xF3n"},{type:"text",content:"La IA no me hace un mejor programador autom\xE1ticamente. Me hace un programador m\xE1s r\xE1pido cuando ya s\xE9 lo que quiero construir. La clave es usarla como amplificador de habilidades existentes, no como reemplazo de la comprensi\xF3n. Si no puedes revisar cr\xEDticamente el c\xF3digo que genera, no est\xE1s listo para usarla en producci\xF3n."}]},{id:2,title:"Arquitectura Multi-Tenant en .NET 9: lecciones de mi sistema ERP/POS",excerpt:"C\xF3mo dise\xF1\xE9 un sistema empresarial SaaS con aislamiento por tenant, firmador electr\xF3nico propio y facturaci\xF3n conectada al Ministerio de Hacienda.",date:"2026-02-08",category:"Arquitectura",tags:[".NET 9","Multi-Tenant","ERP","Clean Architecture","PostgreSQL"],readTime:8,content:[{type:"text",content:'Construir un sistema ERP/POS Multi-Tenant no es solo "agregar un TenantId a las tablas". Es dise\xF1ar desde cero para que m\xFAltiples negocios coexistan de forma segura, eficiente y escalable en una misma infraestructura. Estas son las lecciones que aprend\xED construyendo el m\xEDo con .NET 9 y PostgreSQL.'},{type:"heading",content:"La decisi\xF3n cr\xEDtica: estrategia de aislamiento"},{type:"text",content:"Existen tres enfoques principales para Multi-Tenancy en bases de datos:"},{type:"list",items:["Base de datos por tenant: m\xE1ximo aislamiento, pero costoso y complejo de mantener.","Schema por tenant: buen balance, pero las migraciones se vuelven complicadas.","Discriminador por fila (TenantId): simple, eficiente, pero requiere disciplina en queries."]},{type:"text",content:"Eleg\xED un enfoque h\xEDbrido: un MasterContext centralizado para la gesti\xF3n de negocios, sucursales, usuarios y configuraci\xF3n global, y un POSContext separado por tenant para las operaciones comerciales (ventas, compras, inventario). Esto me da aislamiento real de datos operativos sin la complejidad de manejar N bases de datos."},{type:"heading",content:"Clean Architecture como base"},{type:"text",content:"La estructura del proyecto sigue Clean Architecture estricta. Esto no es opcional en un sistema Multi-Tenant: la separaci\xF3n de capas garantiza que la l\xF3gica de negocio nunca dependa directamente de la infraestructura de tenancy."},{type:"code",label:"Estructura del proyecto",content:`\u251C\u2500\u2500 Domain/           # Entidades, Value Objects, Interfaces
\u2502   \u251C\u2500\u2500 Entities/     # Negocio, Sucursal, PuntoDeVenta, Producto
\u2502   \u2514\u2500\u2500 Interfaces/   # IRepository<T>, ITenantResolver
\u2502
\u251C\u2500\u2500 Application/      # Casos de uso, DTOs, Validators
\u2502   \u251C\u2500\u2500 Features/     # CQRS: Commands y Queries por m\xF3dulo
\u2502   \u2514\u2500\u2500 Mappings/     # Perfiles de mapeo DTO \u2194 Entity
\u2502
\u251C\u2500\u2500 Infrastructure/   # EF Core, Servicios externos
\u2502   \u251C\u2500\u2500 Persistence/  # MasterContext, POSContext, Migrations
\u2502   \u251C\u2500\u2500 DTE/          # Firmador electr\xF3nico, conexi\xF3n MH
\u2502   \u2514\u2500\u2500 Email/        # Servicio SMTP con templates
\u2502
\u2514\u2500\u2500 Api/              # Controllers, Middleware, Filters
    \u251C\u2500\u2500 Middleware/    # TenantResolutionMiddleware
    \u2514\u2500\u2500 Filters/      # TenantAuthorizationFilter`},{type:"heading",content:"Resoluci\xF3n din\xE1mica de tenant"},{type:"text",content:"El middleware de resoluci\xF3n de tenant extrae el identificador del JWT del usuario autenticado y configura el POSContext para apuntar a la base de datos correcta. Todo esto ocurre de forma transparente: los controllers y servicios nunca saben que est\xE1n en un entorno Multi-Tenant."},{type:"code",label:"TenantResolutionMiddleware.cs",content:`public async Task InvokeAsync(HttpContext context)
{
    var tenantId = context.User
        .FindFirst("tenant_id")?.Value;

    if (!string.IsNullOrEmpty(tenantId))
    {
        var resolver = context.RequestServices
            .GetRequiredService<ITenantResolver>();
        await resolver.SetTenantAsync(tenantId);
    }

    await _next(context);
}`},{type:"heading",content:"Firmador electr\xF3nico nativo"},{type:"text",content:"Una decisi\xF3n cr\xEDtica fue construir el firmador de Documentos Tributarios Electr\xF3nicos (DTE) directamente en el backend .NET en lugar de depender de un servicio externo. \xBFPor qu\xE9? Porque cada factura necesita ser firmada criptogr\xE1ficamente con el certificado .p12 del tenant en milisegundos. Un servicio externo introduce latencia, un punto de fallo adicional y costos recurrentes."},{type:"text",content:"El firmador usa System.Security.Cryptography para la firma y est\xE1 dise\xF1ado como servicio Multi-Tenant: cada negocio tiene su propio certificado .p12 almacenado de forma segura, y el pipeline de firma + env\xEDo al MH + recepci\xF3n de sellos se ejecuta en menos de 200ms."},{type:"heading",content:"Seguridad: JWT + roles granulares"},{type:"text",content:'La autenticaci\xF3n usa JWT Bearer con refresh tokens. La autorizaci\xF3n es granular por m\xF3dulo: un usuario puede tener permiso de "Ventas.Crear" sin tener "Ventas.Anular". Los permisos se resuelven desde el token para evitar consultas adicionales a la base de datos en cada request.'},{type:"heading",content:"Lecciones aprendidas"},{type:"list",items:["Soft-delete es obligatorio en Multi-Tenant: nunca elimines datos f\xEDsicamente. Los campos de auditor\xEDa (CreatedAt, UpdatedAt, DeletedAt, CreatedBy) son esenciales.","Las migraciones deben ser idempotentes: cuando tienes m\xFAltiples bases de datos de tenants, una migraci\xF3n que falla a la mitad debe poder re-ejecutarse sin romper nada.","Monitoreo por tenant: si no puedes ver m\xE9tricas por tenant individual, no puedes diagnosticar problemas. Cada log y cada m\xE9trica debe incluir el TenantId.","Provisi\xF3n automatizada: crear un nuevo tenant debe ser un proceso de un clic: base de datos, migraciones, datos semilla, certificados y configuraci\xF3n."]},{type:"text",content:"Multi-Tenant no es un patr\xF3n que agregas despu\xE9s. Es una decisi\xF3n arquitect\xF3nica que permea cada capa del sistema. Si la tomas desde el inicio y aplicas Clean Architecture con disciplina, el resultado es un sistema que escala en clientes sin escalar en complejidad operativa."}]},{id:3,title:"De cero a NPM: c\xF3mo cre\xE9 Prix-R9 y por qu\xE9 cada dev deber\xEDa publicar un paquete",excerpt:"La historia detr\xE1s de Prix-R9, mi CLI de pruebas de carga, y lo que aprend\xED publicando mi primer paquete en NPM.",date:"2026-01-20",category:"Open Source",tags:["Node.js","NPM","CLI","Open Source","Pruebas de carga"],readTime:5,content:[{type:"text",content:"Todo empez\xF3 con una frustraci\xF3n: necesitaba probar la carga de un endpoint que requer\xEDa dos requests encadenados (subir archivo \u2192 ejecutar proceso) y ninguna herramienta existente lo hac\xEDa simple. JMeter es poderoso pero pesado, k6 requiere escribir scripts en JavaScript, y ab/wrk solo soportan requests simples. As\xED naci\xF3 Prix-R9."},{type:"heading",content:"El problema real"},{type:"text",content:"En mi trabajo con el sistema ERP/POS, el flujo de carga de archivos era: 1) subir un CSV con movimientos, 2) extraer el processId del response, 3) enviar ese processId al endpoint de aprobaci\xF3n. Necesitaba simular 50 usuarios concurrentes ejecutando este flujo completo. Las herramientas existentes requer\xEDan scripting complejo o no soportaban la extracci\xF3n de valores entre requests."},{type:"heading",content:"La soluci\xF3n: JSON declarativo"},{type:"text",content:"Dise\xF1\xE9 Prix-R9 para que definir un escenario de carga fuera tan simple como escribir un JSON. Sin scripts, sin lenguajes propietarios. Describes tus steps, defines qu\xE9 extraer de cada response, y la herramienta se encarga del ramp-up, la concurrencia y las m\xE9tricas."},{type:"code",label:"escenario.json",content:`{
  "name": "Flujo de carga completo",
  "startRate": 5,
  "targetRate": 50,
  "rampUpTime": 10,
  "duration": 30,
  "steps": [
    {
      "name": "upload",
      "url": "https://api.example.test/blob/upload",
      "method": "post",
      "file": "./datos.csv",
      "filekey": "File",
      "extract": {
        "processId": "$.uploadFileProcessId"
      }
    },
    {
      "name": "execute",
      "url": "https://api.example.test/approvals/Execute",
      "method": "post",
      "body": {
        "UploadFileProcessId": "{{processId}}"
      }
    }
  ]
}`},{type:"heading",content:"El importador de cURL"},{type:"text",content:"Una feature que result\xF3 ser m\xE1s \xFAtil de lo esperado: prix-r9-curl. Convierte cualquier request exportado como cURL (desde el navegador, Postman o Swagger) a una configuraci\xF3n JSON lista para usar. Esto elimin\xF3 la barrera de entrada: en lugar de escribir JSON desde cero, exportas tu request funcional y la herramienta hace el resto."},{type:"code",label:"Terminal",content:`# Exporta cURL desde el navegador \u2192 convierte \u2192 ejecuta
prix-r9-curl -i curl-upload.txt -o upload.json
prix-r9-curl -i curl-execute.txt -o execute.json

# Combina los JSON en un escenario con steps
# y ejecuta la prueba de carga
prix-r9 --config escenario.json`},{type:"heading",content:"Publicar en NPM: lo que aprend\xED"},{type:"list",items:["Versionado sem\xE1ntico importa: pas\xE9 de 1.0.0 a 2.0.0 cuando a\xF1ad\xED steps (breaking change en el formato JSON). Los usuarios conf\xEDan en semver.","El README es tu landing page: si alguien no entiende qu\xE9 hace tu paquete en 30 segundos, seguir\xE1 buscando. Ejemplos concretos > descripciones abstractas.",'bin en package.json es magia: definir "prix-r9": "index.js" convierte tu script en un comando global. npm install -g y est\xE1 disponible en la terminal.',"Testear el paquete antes de publicar: npm pack --dry-run te muestra exactamente qu\xE9 archivos se incluir\xE1n. Evita publicar node_modules o archivos de desarrollo.","No necesitas un monorepo ni CI/CD sofisticado para empezar: npm publish es suficiente para un paquete personal."]},{type:"heading",content:"Por qu\xE9 todo dev deber\xEDa publicar un paquete"},{type:"text",content:"Publicar un paquete te obliga a pensar como consumidor de tu propio c\xF3digo. Tienes que documentar, versionar, manejar edge cases y dise\xF1ar una API que alguien m\xE1s pueda entender. Es el mejor ejercicio de ingenier\xEDa de software que puedes hacer fuera de tu trabajo diario."},{type:"text",content:"No necesitas crear la pr\xF3xima librer\xEDa que usar\xE1n millones. RMapper (mi micro mapeador para .NET en NuGet) y Prix-R9 son herramientas peque\xF1as que resuelven problemas espec\xEDficos que yo ten\xEDa. Y eso es suficiente: si te resolvi\xF3 un problema a ti, probablemente le resuelva el mismo problema a alguien m\xE1s."},{type:"heading",content:"Lo que sigue"},{type:"text",content:"Prix-R9 est\xE1 en v2.0.4 y sigo iterando. Las pr\xF3ximas features incluyen reportes en formato HTML con gr\xE1ficas de latencia y un modo watch para re-ejecutar pruebas autom\xE1ticamente cuando cambia la configuraci\xF3n. Si te interesa probarlo: npm install -g prix-r9."}]}],s=class a{postsResource=i({params:()=>({}),stream:()=>n(d).pipe(o(400))});getPostById(t){let e=this.postsResource.value();if(e&&Array.isArray(e))return e.find(c=>c.id===t)}static \u0275fac=function(e){return new(e||a)};static \u0275prov=r({token:a,factory:a.\u0275fac,providedIn:"root"})};export{s as a};
